    private static ComponentReferenceSpec board(String name, VisionPoint[] corners, VisionPoint[][] regions) {
        return build("main_board_brackets_"+name,NeobotSeedData.MAIN_BOARD,"Main board",
                "references/assembly-captures/main-board-brackets-20260927_"+name+".jpg",
                100,120,corners,regions,false);
    }
    private static ComponentReferenceSpec face(String name,double width,double height,VisionPoint[] corners,VisionPoint[][] regions) {
        return build("motor_bracket_installed_"+name,NeobotSeedData.MOTOR_BRACKET,"Installed motor bracket",
                "references/installed-brackets-20260927/motor-bracket-"+name+".jpg",
                width,height,corners,regions,true);
    }
    private static ComponentReferenceSpec build(String id,String component,String label,String asset,
            double width,double height,VisionPoint[] corners,VisionPoint[][] polygons,boolean face) {
        List<List<VisionPoint>> regions=new ArrayList<>();
        for(VisionPoint[] polygon:polygons) regions.add(Arrays.asList(polygon));
        return ComponentReferenceSpec.builder(id,component,label,width,height).jpegAssetPath(asset)
                .assemblyStepNumber(2).installedBracketView(face).maximumImageDimension(1280)
                .polarityAnchorsVerified(false).featureRegionsNormalized(regions)
                .planarReferenceCornersNormalized(corners[0],corners[1],corners[2],corners[3]).build();
    }
